import React, { useEffect, useState } from 'react';
import { Link, useParams } from 'react-router-dom';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { externalApi } from '../../../api/external';
import { ActionButton, ErrorMessage, Loading, PageTitle, Panel } from '../../shared/PhaseUi';

const initial = { summary: '', strengths: '', weaknesses: '', questions: '', rating: '', confidence: '', recommendation: '', confidential_comments: '' };
export default function ExternalReviewPage() {
  const { paperId } = useParams(); const qc = useQueryClient(); const [form, setForm] = useState(initial);
  const query = useQuery({ queryKey: ['external-review', paperId], queryFn: () => externalApi.getReview(paperId) });
  useEffect(() => { if (query.data) setForm(old => ({ ...old, ...Object.fromEntries(Object.keys(initial).map(k => [k, query.data[k] ?? ''])) })); }, [query.data]);
  const mutation = useMutation({ mutationFn: (submit) => externalApi.saveReview(paperId, { ...form, rating: form.rating === '' ? null : Number(form.rating), confidence: form.confidence === '' ? null : Number(form.confidence), submit }), onSuccess: data => qc.setQueryData(['external-review', paperId], data) });
  if (query.isLoading) return <Loading label="Loading assigned paper…" />;
  if (query.isError) return <div className="p-6"><ErrorMessage error={query.error} /></div>;
  const data = query.data || {}; const locked = data.status === 'submitted';
  const set = (k,v) => setForm(f => ({ ...f, [k]: v }));
  return <div className="p-6 max-w-4xl mx-auto text-white space-y-5"><Link to="/external/assignments" className="text-sm text-[#ff8b6e] hover:underline">← External assignments</Link><PageTitle eyebrow="Phase 8 · Double-blind" title={data.paper_title || `Paper ${paperId}`} subtitle={`${data.paper_number || ''} · Reviewer identity and author identities are not exposed here.`} /><Panel><h2 className="font-semibold mb-2">Abstract</h2><p className="text-sm text-gray-300 whitespace-pre-wrap">{data.paper_abstract || 'Abstract unavailable.'}</p></Panel><Panel className="space-y-4"><h2 className="text-lg font-semibold">External review form</h2>{[['summary','Summary'],['strengths','Strengths'],['weaknesses','Weaknesses'],['questions','Questions for authors'],['confidential_comments','Confidential note to committee']].map(([k,label]) => <label key={k} className="block text-sm">{label}<textarea disabled={locked} value={form[k]} onChange={e => set(k,e.target.value)} rows={3} maxLength={12000} className="mt-1 w-full bg-[#121214] border border-white/10 rounded-xl p-3 disabled:opacity-50" /></label>)}<div className="grid sm:grid-cols-3 gap-3">{[['rating','Rating'],['confidence','Confidence']].map(([k,label]) => <label key={k} className="text-sm">{label}<select disabled={locked} value={form[k]} onChange={e => set(k,e.target.value)} className="block mt-1 w-full bg-[#121214] border border-white/10 rounded-xl p-2"><option value="">Choose…</option>{[1,2,3,4,5].map(n => <option key={n} value={n}>{n}</option>)}</select></label>)}<label className="text-sm">Recommendation<select disabled={locked} value={form.recommendation} onChange={e => set('recommendation',e.target.value)} className="block mt-1 w-full bg-[#121214] border border-white/10 rounded-xl p-2"><option value="">Choose…</option>{['accept','weak_accept','borderline','weak_reject','reject'].map(v => <option key={v} value={v}>{v.replace('_',' ')}</option>)}</select></label></div>{mutation.isError && <p className="text-red-300 text-sm">{mutation.error?.response?.data?.detail || 'Save failed.'}</p>}<div className="flex gap-2">{!locked && <><ActionButton variant="secondary" busy={mutation.isPending} onClick={() => mutation.mutate(false)}>Save draft</ActionButton><ActionButton busy={mutation.isPending} disabled={!form.summary || !form.strengths || !form.weaknesses || !form.rating || !form.confidence || !form.recommendation} onClick={() => { if (window.confirm('Submit your review? It may be locked after submission.')) mutation.mutate(true); }}>Submit review</ActionButton></>}{locked && <p className="text-green-300 text-sm">Review submitted.</p>}</div></Panel></div>;
}
